import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"科技“武装”庄浪梯田：智慧农业“蔬”写致富径","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"科技“武装”庄浪梯田：智慧农业“蔬”写致富径","date":"2026-07-10T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260626_6485316.htm","summary":"中新网甘肃新闻6月23日电(董春辉 高国霞)夏日的平凉庄浪,梯田层叠如画。在这片充满生机的土地上,一排排整齐排列的现代化大棚格外引人注目,正悄然改变着千百年来“面朝黄土背朝天”的传统耕作方式。\\n图为庄浪县良邑镇现代智慧农业产业园。 董春辉 摄\\n走进庄浪县良邑镇现代智慧农业产业园,高科技装备一应俱全、高效运转。...\\n","contentHash":"a316c4045761337ef876dff880163a41","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-07-10-科技-武装-庄浪梯田-智慧农业-蔬-写致富径.md","filePath":"news/2026-07-10-科技-武装-庄浪梯田-智慧农业-蔬-写致富径.md"}'),n={name:"news/2026-07-10-科技-武装-庄浪梯田-智慧农业-蔬-写致富径.md"};function s(o,e,p,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="科技-武装-庄浪梯田-智慧农业-蔬-写致富径" tabindex="-1">科技“武装”庄浪梯田：智慧农业“蔬”写致富径 <a class="header-anchor" href="#科技-武装-庄浪梯田-智慧农业-蔬-写致富径" aria-label="Permalink to &quot;科技“武装”庄浪梯田：智慧农业“蔬”写致富径&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260626_6485316.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-07-10 摘要: 中新网甘肃新闻6月23日电(董春辉 高国霞)夏日的平凉庄浪,梯田层叠如画。在这片充满生机的土地上,一排排整齐排列的现代化大棚格外引人注目,正悄然改变着千百年来“面朝黄土背朝天”的传统耕作方式。 图为庄浪县良邑镇现代智慧农业产业园。 董春辉 摄 走进庄浪县良邑镇现代智慧农业产业园,高科技装备一应俱全、高效运转。...</p></blockquote><p>走进庄浪县良邑镇现代智慧农业产业园,高科技装备一应俱全、高效运转。水肥一体化系统精准配比营养液,物联网传感器实时监测环境参数,4G智能放风机自动调节棚内温湿度。这些“智慧管家”精确调控着每一株果蔬的“温、光、水、气、肥”,为作物生长打造出最适宜的“定制化”环境。</p><p>该产业园负责人陈登华介绍说:“园区一期主要种植西红柿、辣椒、黄瓜等果蔬,目前已全面进入销售旺季。二期种植铁皮草莓西红柿,我们已与海底捞、北京物美、京东7鲜等企业签订合作订单,走出了一条精准化、订单化的特色农业发展之路。”</p><p>正是得益于这份精准的数字化照料,棚内的各色果蔬都铆足了劲儿生长。西红柿亩产可达1.5万斤,黄瓜甚至能突破2万斤。网络上备受追捧的“网红”白色贝贝南瓜,一上市就被抢购一空。这些数字背后,是智慧农业对传统种植方式颠覆性变革的有力印证。</p><p>智慧农业改变的不仅是种植方式,更是当地农民的生活面貌。该项目建成以来,已累计为周边村民提供了200多个就近就业岗位,实现了“赚钱顾家两不误”的乡亲们的心愿。良邑镇何川村村民张红霞说:“自从园区建成,我就一直在这儿干活,既能照顾上家里,每个月还有3000元的收入,一年下来能挣3万多元,日子越过越踏实,我感觉特别好。”</p><p>从“靠天吃饭”到“知天而作”,从传统农业到智慧农业,庄浪县良邑镇现代智慧农业产业园的实践,正是农业现代化发展的生动缩影。良邑镇党委副书记柳渊表示:“我们按照‘政府主导、企业参与、市场运作、多方共赢’的思路,采取‘党组织+企业+合作社+基地+农户’的联动发展模式,通过土地流转、入股分红、园区务工、技术培训、种苗供应、订单种植等联农带农机制,实现了农户增收、村集体壮大、企业盈利三方共赢。下一步,我们将打造辐射全县的设施蔬菜和高原夏菜集散中心,真正让特色农业成为群众稳定增收的硬核支撑。”</p><p>夏日悠长,万物繁茂。在这片被科技“武装”的沃土上,现代智慧农业产业园正以产业为纽带,连起千家万户的增收梦想,书写着乡村振兴的崭新篇章。从“汗水农业”迈向“智慧农业”,庄浪正用科技之笔,在梯田大地上描绘出一幅农业强、农村美、农民富的时代画卷。(完)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260626_6485316.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',9)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
